for sid, body in STATES.items():
    path = os.path.join(ROOT, sid + ".json")
    with open(path) as f:
        d = json.load(f)
    assert d["states"][-1]["date"] < DATE, sid
    d["states"].append({"date": DATE, "text": body["text"], "changed": body["changed"]})
    for fig in FIGURES.get(sid, []):
        d.setdefault("figures", []).append(fig)
    for q in QUESTIONS.get(sid, []):
        d.setdefault("questions", []).append(q)
    with open(path, "w") as f:
        json.dump(d, f, indent=2, ensure_ascii=False)
        f.write("\n")
    print("updated", sid)

